19	
20	class HttpError extends Error {
21	  constructor(status, message) {
22	    super(message);
23	    this.status = status;
24	  }
25	}
26	
27	// ---------- validation ----------
28	
29	function isPlainObject(value) {
30	  return typeof value === 'object' && value !== null && !Array.isArray(value);
31	}
32	
33	function isValidDate(value) {
34	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
35	  const year = Number(value.slice(0, 4));
36	  const month = Number(value.slice(5, 7));
37	  const day = Number(value.slice(8, 10));
38	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
39	  const febDays = year % 4 === 0 ? 29 : 28;
40	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
41	  return day <= monthDays[month - 1];
42	}
43	
44	function isValidTime(value) {
45	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
46	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
47	}
48	
49	function isValidTitle(value) {
50	  if (typeof value !== 'string') return false;
51	  const { length } = value.trim();
52	  return length >= 1 && length <= 80;
53	}
54	
55	/** Applies booking rules 4-9 to a parsed body; returns the normalised fields. */
56	function validateFields(body) {
57	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) {
58	    throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
59	  }
60	  if (!isValidTitle(body.title)) throw new HttpError(400, 'title must be 1 to 80 characters');
61	  if (!isValidDate(body.date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
62	  if (!isValidTime(body.start)) throw new HttpError(400, 'start must be HH:MM');
63	  if (!isValidTime(body.end)) throw new HttpError(400, 'end must be HH:MM');
64	  if (body.end <= body.start) throw new HttpError(400, 'end must be after start');
65	  return { room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end };
66	}
67	
68	function hasExactKeys(obj, keys) {
69	  const own = Object.keys(obj).sort();
70	  return own.length === keys.length && own.every((key, i) => key === keys[i]);
71	}
72	
73	function isStoredBooking(b) {
74	  return isPlainObject(b) && hasExactKeys(b, [...BOOKING_KEYS].sort())
75	    && Number.isSafeInteger(b.id) && b.id >= 1
76	    && ROOMS.includes(b.room) && isValidTitle(b.title) && b.title === b.title.trim()
77	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
78	}
79	
80	function findOverlaps(bookings, candidate) {
81	  return bookings.filter((b) => b.room === candidate.room && b.date === candidate.date
82	    && b.start < candidate.end && candidate.start < b.end);
83	}
84	
85	/** Returns the stored state if `data` is exactly the layout this server writes, else null. */
86	function parseStoredData(data) {
87	  if (!isPlainObject(data) || !hasExactKeys(data, DATA_KEYS)) return null;
88	  const { nextId, bookings } = data;
89	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return null;
90	  const seen = new Set();
91	  for (const [index, b] of bookings.entries()) {
92	    if (!isStoredBooking(b) || b.id >= nextId || seen.has(b.id)) return null;
93	    if (findOverlaps(bookings.slice(0, index), b).length > 0) return null;
94	    seen.add(b.id);
95	  }
96	  return { nextId, bookings: bookings.map((b) => ({ ...b })) };
97	}
98	
99	// ---------- storage ----------
100	
101	function createStore(filePath, initial) {
102	  let state = initial;
103	  let queue = Promise.resolve();
104	
105	  async function save(next) {
106	    await writeFile(filePath, JSON.stringify(next));
107	    state = next;
108	  }
109	
110	  /** Runs mutations one at a time so concurrent requests see a consistent state. */
111	  function serialize(task) {
112	    const result = queue.then(() => task(state, save));
113	    queue = result.catch(() => {});
114	    return result;
115	  }
116	
117	  return { get: () => state, serialize };
118	}
119	
120	async function loadState(filePath) {
121	  let text;
122	  try {
123	    text = await readFile(filePath, 'utf8');
124	  } catch (err) {
125	    if (err && err.code === 'ENOENT') return { nextId: 1, bookings: [] };
126	    return null;
127	  }
128	  try {
129	    return parseStoredData(JSON.parse(text));
130	  } catch {
131	    return null;
132	  }
133	}
134	
135	// ---------- HTTP helpers ----------
136	
137	function sendJson(res, status, payload) {
138	  const body = JSON.stringify(payload);
139	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
140	  res.end(body);
141	}
142	
143	function sendError(res, status, message) {
144	  sendJson(res, status, { error: message });
145	}
146	
147	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes and counts the rest. */
148	async function readBody(req) {
149	  const chunks = [];
150	  let kept = 0;
151	  let total = 0;
152	  for await (const chunk of req) {
153	    total += chunk.length;
154	    if (kept <= MAX_BODY_BYTES) {
155	      const piece = chunk.subarray(0, MAX_BODY_BYTES + 1 - kept);
156	      chunks.push(piece);
157	      kept += piece.length;
158	    }
159	  }
160	  return { buffer: Buffer.concat(chunks), total };
161	}
162	
163	function isJsonContentType(header) {
164	  if (typeof header !== 'string') return false;
165	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
166	  return media.toLowerCase() === 'application/json';
167	}
168	
169	function compareText(key) {
170	  return (a, b) => {
171	    if (a[key] === b[key]) return 0;
172	    return a[key] < b[key] ? -1 : 1;
173	  };
174	}
175	
176	const byDate = compareText('date');
177	const byStart = compareText('start');
178	
179	function compareBookings(a, b) {
180	  return byDate(a, b) || byStart(a, b) || ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
181	}
182	
183	// ---------- handlers ----------
184	
185	function listBookings(store, query, res) {
186	  const params = new URLSearchParams(query);
187	  const date = params.has('date') ? params.get('date') : null;
188	  if (date !== null && !isValidDate(date)) {
189	    throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
190	  }
191	  const bookings = store.get().bookings.filter((b) => date === null || b.date === date);
192	  sendJson(res, 200, { bookings: bookings.sort(compareBookings) });
193	}
194	
195	function parseBookingBody(req, body) {
196	  if (!isJsonContentType(req.headers['content-type'])) {
197	    throw new HttpError(415, 'content type must be application/json');
198	  }
199	  if (body.total > MAX_BODY_BYTES) throw new HttpError(413, 'body too large');
200	  let parsed;
201	  try {
202	    parsed = JSON.parse(body.buffer.toString('utf8'));
203	  } catch {
204	    parsed = undefined;
205	  }
206	  if (!isPlainObject(parsed)) throw new HttpError(400, 'body must be a JSON object');
207	  return validateFields(parsed);
208	}
209	
210	async function createBooking(store, req, body, res) {
211	  const fields = parseBookingBody(req, body);
212	  const booking = await store.serialize(async (state, save) => {
213	    const overlaps = findOverlaps(state.bookings, fields).sort(compareText('start'));
214	    if (overlaps.length > 0) {
215	      throw new HttpError(409, `room is already booked from ${overlaps[0].start} to ${overlaps[0].end}`);
216	    }
217	    const created = { id: state.nextId, ...fields };
218	    await save({ nextId: state.nextId + 1, bookings: [...state.bookings, created] });
219	    return created;
220	  });
221	  sendJson(res, 201, booking);
222	}
223	
224	async function deleteBooking(store, idText, res) {
225	  if (!/^[1-9][0-9]*$/.test(idText)) throw new HttpError(404, 'booking not found');
226	  await store.serialize(async (state, save) => {
227	    const remaining = state.bookings.filter((b) => String(b.id) !== idText);
228	    if (remaining.length === state.bookings.length) throw new HttpError(404, 'booking not found');
229	    await save({ nextId: state.nextId, bookings: remaining });
230	  });
231	  res.writeHead(204);
232	  res.end();
233	}
234	
235	async function serveStatic(entry, res) {
236	  const content = await readFile(path.join(PUBLIC_DIR, entry.file));
237	  res.writeHead(200, { 'Content-Type': entry.type, 'Content-Length': content.length });
238	  res.end(content);
239	}
240	
241	const BOOKING_PREFIX = '/api/bookings/';
242	
243	/** Dispatches by exact path bytes and method; throws 404/405 when no route matches. */
244	async function route(store, req, res, body) {
245	  const target = req.url;
246	  const q = target.indexOf('?');
247	  const pathname = q === -1 ? target : target.slice(0, q);
248	  const query = q === -1 ? '' : target.slice(q + 1);
249	  const { method } = req;
250	  const expect = (allowed) => {
251	    if (!allowed.includes(method)) throw new HttpError(405, 'method not allowed');
252	  };
253	  if (Object.hasOwn(STATIC_FILES, pathname)) {
254	    expect(['GET']);
255	    return serveStatic(STATIC_FILES[pathname], res);
256	  }
257	  if (pathname === '/api/rooms') {
258	    expect(['GET']);
259	    return sendJson(res, 200, { rooms: [...ROOMS] });
260	  }
261	  if (pathname === '/api/bookings') {
262	    expect(['GET', 'POST']);
263	    return method === 'GET' ? listBookings(store, query, res) : createBooking(store, req, body, res);
264	  }
265	  const rest = pathname.startsWith(BOOKING_PREFIX) ? pathname.slice(BOOKING_PREFIX.length) : '';
266	  if (rest !== '' && !rest.includes('/')) {
267	    expect(['DELETE']);
268	    return deleteBooking(store, rest, res);
269	  }
270	  throw new HttpError(404, 'not found');
271	}
272	
273	function createHandler(store) {
274	  return async (req, res) => {
275	    let body;
276	    try {
277	      body = await readBody(req);
278	    } catch {
279	      res.destroy();
280	      return;
281	    }
282	    try {
283	      await route(store, req, res, body);
284	    } catch (err) {
285	      if (res.headersSent) {
286	        res.destroy();
287	      } else if (err instanceof HttpError) {
288	        sendError(res, err.status, err.message);
289	      } else {
290	        sendError(res, 500, 'internal error');
291	      }
292	    }
293	  };
294	}
295	
296	// ---------- startup ----------
297	
298	function parsePort(raw) {
299	  if (raw === undefined || raw === '') return DEFAULT_PORT;
300	  if (!/^[0-9]+$/.test(raw)) return null;
301	  const port = Number(raw);
302	  return port <= 65535 ? port : null;
303	}
304	
305	function fail(line) {
306	  process.stderr.write(`${line}\n`);
307	  process.exitCode = 1;
308	}
309	
310	async function main() {
311	  const port = parsePort(process.env.PORT);
312	  if (port === null) return fail('invalid PORT');
313	
314	  const dataName = process.env.DATA_FILE || DEFAULT_DATA_FILE;
315	  const dataPath = path.resolve(process.cwd(), dataName);
316	  const initial = await loadState(dataPath);
317	  if (initial === null) return fail(`cannot read data file ${dataName}`);
318	
319	  const store = createStore(dataPath, initial);
320	  const server = http.createServer(createHandler(store));
321	  server.on('error', (err) => {
322	    const reason = err && err.code === 'EADDRINUSE' ? 'is already in use' : 'cannot be used';
323	    fail(`port ${port} ${reason}`);
324	    process.exit(1);
325	  });
326	  server.listen(port, HOST, () => {
327	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
328	  });
329	}
330	
331	main().catch(() => {
332	  fail('server failed to start');
333	  process.exit(1);
334	});
